const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
const esc=(s)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=()=>({consent:false,captured:false,note:'',signed:false,version:1,history:[],formFilled:false,formReviewed:false,settings:{ai:true,speech:true,sms:false},tasks:[{text:'Review Maya’s consultation summary',owner:'Dr Morgan',done:false},{text:'Confirm follow-up appointment preference',owner:'Care team',done:false},{text:'Prepare Alex’s pre-appointment briefing',owner:'Admin team',done:false}],audit:[{time:'09:00',text:'Demo workspace opened. All records are fictional.'}]});
// Validate known persisted fields before any renderer or migration uses them.
function validSavedWorkspace(value){
 const object=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
 const strings=(v,keys)=>keys.every(k=>v[k]===undefined||typeof v[k]==='string');
 const booleans=(v,keys)=>keys.every(k=>v[k]===undefined||typeof v[k]==='boolean');
 const fields=v=>Array.isArray(v)&&v.every(f=>object(f)&&['label','value','original','source'].every(k=>typeof f[k]==='string')&&typeof f.reviewed==='boolean');
 const patientIds=['DEMO-001','DEMO-002','DEMO-003'];
 const patientMap=(v,check)=>object(v)&&Object.entries(v).every(([id,item])=>patientIds.includes(id)&&object(item)&&check(item,id));
 const snapshot=(v,id)=>object(v)&&v.patientId===id&&fields(v.fields)&&strings(v,['at','status']);
 const record=(v,id)=>object(v)&&strings(v,['note','noteTemplate'])&&booleans(v,['consent','captured','signed','formFilled','formReviewed'])
  &&['version','revision'].every(k=>v[k]===undefined||(Number.isInteger(v[k])&&v[k]>=(k==='version'?1:0)))
  &&(v.history===undefined||(Array.isArray(v.history)&&v.history.every(h=>object(h)&&typeof h.text==='string'&&typeof h.status==='string'&&Number.isInteger(h.version)&&h.version>0&&(h.patientId===undefined||h.patientId===id))))
  &&(v.formData==null||fields(v.formData))
  &&(v.formApproval==null||snapshot(v.formApproval,id));
 if(!record(value,'DEMO-001')||!object(value.settings)||!['ai','speech','sms'].every(k=>typeof value.settings[k]==='boolean'))return false;
 if(!Array.isArray(value.tasks)||!value.tasks.every(t=>object(t)&&typeof t.text==='string'&&typeof t.owner==='string'&&typeof t.done==='boolean'))return false;
 if(!Array.isArray(value.audit)||!value.audit.every(a=>object(a)&&typeof a.time==='string'&&typeof a.text==='string'))return false;
 if(value.schemaVersion!==undefined&&value.schemaVersion!==1)return false;
 if(value.patientRecords!==undefined&&!patientMap(value.patientRecords,record))return false;
 if(value.selectedPatientId!==undefined&&!['DEMO-001','DEMO-002','DEMO-003'].includes(value.selectedPatientId))return false;
 if(value.consultationUi!==undefined&&!patientMap(value.consultationUi,c=>['identityChecked','reviewed','paused'].every(k=>typeof c[k]==='boolean')&&Number.isSafeInteger(c.elapsed)&&c.elapsed>=0))return false;
 if(value.patientPreparation!==undefined&&!patientMap(value.patientPreparation,p=>object(p.checks)&&Object.entries(p.checks).every(([key,v])=>['sources','gaps','agenda'].includes(key)&&typeof v==='boolean')&&typeof p.note==='string'&&(p.fingerprint===null||typeof p.fingerprint==='string')))return false;
 if(value.formUi!==undefined&&!patientMap(value.formUi,(f,id)=>Number.isSafeInteger(f.version)&&f.version>0&&Array.isArray(f.history)&&f.history.every(h=>object(h)&&Number.isSafeInteger(h.version)&&h.version>0&&typeof h.status==='string'&&snapshot(h.snapshot,id))))return false;
 if(value.handoverDrafts!==undefined&&(!Array.isArray(value.handoverDrafts)||!value.handoverDrafts.every(d=>object(d)&&patientIds.includes(d.patientId)&&['patientName','sourceNote','recipient','message','createdAt'].every(k=>typeof d[k]==='string')&&Number.isSafeInteger(d.sourceVersion)&&d.sourceVersion>0&&Number.isSafeInteger(d.sourceRevision)&&d.sourceRevision>=0&&d.deliveryStatus==='not-sent')))return false;
 if(value.eprHandoffDrafts!==undefined&&(!Array.isArray(value.eprHandoffDrafts)||!value.eprHandoffDrafts.every(d=>object(d)&&patientIds.includes(d.patientId)&&['patientName','sourceText','sourceTemplate','context','createdAt'].every(k=>typeof d[k]==='string')&&['rio','emis','other'].includes(d.destination)&&Number.isSafeInteger(d.sourceVersion)&&d.sourceVersion>0&&Number.isSafeInteger(d.sourceRevision)&&d.sourceRevision>=0&&d.submissionStatus==='NOT_SENT'&&d.acknowledgement===null&&d.retentionAction==='NONE')))return false;
 if(value.product!==undefined){
  const p=value.product;if(!object(p)||!strings(p,['service','theme','role','team','contact','pilotNotes']))return false;
  if(p.planNotes!==undefined&&(!object(p.planNotes)||!Object.values(p.planNotes).every(v=>typeof v==='string')))return false;
  if(p.extensions!==undefined&&(!object(p.extensions)||!Object.values(p.extensions).every(e=>object(e)&&strings(e,['reason','date'])&&booleans(e,['requested']))))return false;
 }
 return true;
}
let state,storageBaseline=null,storageLoadFailed=false;
try{
 storageBaseline=localStorage.getItem('clinical-admin-demo-v1');
 if(storageBaseline===null)state=initial();
 else{const loaded=JSON.parse(storageBaseline);if(!validSavedWorkspace(loaded))throw Error('unsupported_saved_workspace');state=loaded;}
}catch{state=initial();storageLoadFailed=true;}

let route='home',filterStatus='all',filterCat='all',search='',categoryTab='workflow',recording=false,seconds=0,recordTimer,toastTimer,tourIndex=0;
let storageSaveFailed=storageLoadFailed,storageConflict=false;
function showStorageStatus(){
 if(typeof refreshPreparationSaveStatus==='function')refreshPreparationSaveStatus();
 const banner=document.getElementById('storage-status');if(!banner)return;
 banner.hidden=!storageSaveFailed;
 document.getElementById('storage-message').textContent=storageConflict
  ?'Another tab changed or cleared the saved demo. Saving from this tab is blocked to avoid overwriting those records. Export this tab’s changes if needed, then reload the saved version.'
  :storageLoadFailed?'The saved demo could not be loaded. This is a temporary fresh preview; saving is blocked to preserve the original. Export the original saved value if available before choosing Reset demo data in settings.':storageSaveFailed?'Changes are not saved. They exist only in this tab and may be lost if you reload or close it. Free browser storage or allow site storage, then retry.':'';
 document.getElementById('storage-retry').hidden=storageConflict||storageLoadFailed;
 document.getElementById('storage-original').hidden=!storageLoadFailed||storageBaseline===null;
 document.getElementById('storage-reload').hidden=!storageConflict&&!storageLoadFailed;
}
function save(){
 if(storageLoadFailed){storageSaveFailed=true;showStorageStatus();return false;}
 try{
  if(storageConflict||localStorage.getItem('clinical-admin-demo-v1')!==storageBaseline){storageConflict=true;storageSaveFailed=true;showStorageStatus();return false;}
  const snapshot=JSON.stringify(state);
  localStorage.setItem('clinical-admin-demo-v1',snapshot);storageBaseline=snapshot;
  storageSaveFailed=false;showStorageStatus();return true;
 }catch{storageSaveFailed=true;showStorageStatus();return false;}
}
function exportStoredRecovery(){if(storageBaseline!==null)download('clinical-admin-original-storage.json',JSON.stringify({status:'UNREADABLE_DEMO_STORAGE_NOT_FOR_IMPORT',original:storageBaseline},null,2),'application/json');}
function exportRecovery(){download('clinical-admin-tab-recovery.json',JSON.stringify({status:'DEMO_LOCAL_RECOVERY_NOT_FOR_IMPORT',exportedAt:new Date().toISOString(),workspace:state},null,2),'application/json');}
function confirmReloadSaved(){modal('Reload saved demo?', '<p>This discards changes held only in this tab and loads the current saved demo. Export this tab’s changes first if you need to keep them.</p>', '<button onclick="closeModal()">Keep this tab</button><button class="primary" onclick="reloadSavedState()">Discard tab changes and reload</button>');}
function reloadSavedState(){storageSaveFailed=false;location.reload();}
window.addEventListener?.('storage',event=>{
 if(event.storageArea!==localStorage||(event.key!==null&&event.key!=='clinical-admin-demo-v1'))return;
 if(event.newValue!==storageBaseline){storageConflict=true;storageSaveFailed=true;showStorageStatus();}
});
function retrySave(){if(save())toast('Demo changes saved in this browser.');}
window.addEventListener?.('beforeunload',event=>{if(storageSaveFailed){event.preventDefault();event.returnValue='';}});
function audit(text){state.audit.unshift({time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}),text});return save()}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',4200)}
function pill(s){return `<span class="pill ${statusInfo[s].color}">${statusInfo[s].label}</span>`}
const catFor=key=>categories.find(c=>c.key===key);
function count(status,cat){return features.filter(f=>(!status||f.status===status)&&(!cat||f.cat===cat)).length}
function nav(to){if(recording)pauseRecord();closeModal();route=to;categoryTab='workflow';document.getElementById('sidebar').classList.remove('open');render();window.scrollTo(0,0);if(location.hash!=='#'+to)(history.pushState||history.replaceState).call(history,null,'','#'+to);document.getElementById('main').focus?.({preventScroll:true})}
function catalogue(status='all',cat='all',q=''){filterStatus=status;filterCat=cat;search=q;nav('catalogue')}
function head(title,subtitle,actions='',eyebrow='CLINICAL ADMIN / WORKSPACE'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`}
function render(){renderSidebar();document.getElementById('topbar').innerHTML=`<button class="mobile-menu top-icon" aria-label="Open navigation" onclick="document.getElementById('sidebar').classList.toggle('open')">${icon('menu')}</button><div class="breadcrumb">Workspace <span style="margin:0 10px;color:#b6c6ca">/</span> <b>${esc(catFor(route)?.short||({home:'Overview',catalogue:'All functions',patients:'Patient context',settings:'Demo settings'}[route]||'Overview'))}</b></div><form class="top-search" onsubmit="event.preventDefault();catalogue('all','all',this.query.value)">${icon('search')}<input name="query" aria-label="Search all functions" placeholder="Search functions, IDs, workflows…"><span style="font-size:10px">↵</span></form><button class="top-icon" aria-label="Demo settings" onclick="nav('settings')">${icon('settings')}</button><div class="avatar" title="Fictional clinician">JM</div>`;
 const root=document.getElementById('main');root.innerHTML=route==='home'?home():route==='catalogue'?cataloguePage():route==='patients'?patientPage():route==='settings'?settingsPage():categoryPage(route);if(route==='catalogue')renderResults();}
function renderSidebar(){document.getElementById('sidebar').innerHTML=`<div class="brand"><div class="brand-mark">${icon('heart')}</div><div><strong>DeepSynaps</strong><small>CLINICAL ADMIN</small></div></div><div class="org">${icon('people')}<div><strong>NHS demonstration workspace</strong><small>Community care · Fictional organisation</small></div></div><nav aria-label="Main navigation"><div class="nav-label">YOUR WORKSPACE</div>${navButton('home','grid','Overview')}${navButton('patients','people','Patients & appointments')}<div class="nav-label">CLINICAL TOOLS</div>${categories.map(c=>navButton(c.key,c.icon,c.short,count(null,c.key))).join('')}<div class="nav-label">EXPLORE</div>${navButton('catalogue','grid','All functions',158)}${navButton('settings','settings','Demo settings')}</nav><div class="side-bottom"><div class="connected"><strong>Powered by DeepSynaps</strong>Clinical Intelligence OS<br><span style="font-size:10px">API connection simulated in this demo</span></div><div class="profile"><div class="avatar">JM</div><div>Dr Jamie Morgan<small>Demo clinician</small></div></div></div>`}
function navButton(id,i,title,total){return `<button class="${route===id?'active':''}" onclick="nav('${id}')" ${route===id?'aria-current="page"':''}>${icon(i)}<span>${title}</span>${total?`<span class="nav-count">${total}</span>`:''}</button>`}
function home(){return head('A clearer day. Better connected care.','Your clinical tools, patient context and daily admin. All in one workspace.',`<button class="button-icon" onclick="startTour()">${icon('play')} Take a guided tour</button><button class="primary button-icon" onclick="nav('C')">${icon('plus')} New consultation</button>`,'DEEPSYNAPS • NHS WORKSPACE DEMO')+`<div class="stats"><button class="stat first" onclick="catalogue()"><div class="stat-top">Complete workspace ${icon('grid')}</div><div class="stat-value">158</div><div class="stat-bottom">functions across <b>8 categories</b></div></button><button class="stat" onclick="catalogue('operational')"><div class="stat-top">Reported end-to-end ${icon('check')}</div><div class="stat-value">91 <span class="pill green" style="vertical-align:middle;margin-left:5px">Operational*</span></div><div class="stat-bottom"><b>68 ready</b> · 23 require services</div></button><button class="stat" onclick="catalogue('linked')"><div class="stat-top">Connected intelligence ${icon('link')}</div><div class="stat-value">31</div><div class="stat-bottom">existing DeepSynaps modules</div></button><button class="stat" onclick="catalogue('pending')"><div class="stat-top">Readiness & scope ${icon('shield')}</div><div class="stat-value">36</div><div class="stat-bottom">pending dependencies or excluded</div></button></div><div class="content-grid"><section><div class="section-head"><div><h2>Your clinical workspace</h2><p>Choose a tool to explore its workflow and capabilities.</p></div><button class="text-btn" onclick="catalogue()">View all 158 ↗</button></div><div class="category-grid">${categories.map(c=>`<button class="category-card" onclick="nav('${c.key}')"><span class="card-arrow">${icon('arrow')}</span><div class="card-icon ${c.color}">${icon(c.icon)}</div><h3>${c.name}</h3><p>${c.desc}</p><div class="card-foot"><span>${count(null,c.key)} functions</span><span>·</span><span class="pill green">${count('ready',c.key)+count('enabled',c.key)} operational*</span>${count('linked',c.key)?`<span>${count('linked',c.key)} linked</span>`:''}</div></button>`).join('')}</div><div class="journey">${icon('play')}<div><h3>Follow one patient’s journey</h3><p>Appointment → conversation → reviewed note → follow-up.</p></div><button onclick="startTour()">Start walkthrough ↗</button></div></section><aside class="right-rail"><div class="panel"><div class="panel-head"><h3>Today’s clinic</h3><span class="pill grey">Demo day</span></div><div class="day">${icon('calendar')} Tuesday, 13 October · Fictional schedule</div>${appointment('09:15','MC','Maya Collins','Follow-up · Community care',true)}${appointment('10:00','AT','Alex Taylor','Initial consultation',false)}${appointment('10:45','SW','Sam Wilson','Care plan review',false)}<button class="wide" onclick="nav('patients')">View patients & appointments →</button></div><div class="panel"><div class="panel-head"><h3>Designed for human oversight</h3>${icon('shield')}</div><p class="fine">Review and sign before any document leaves the clinical workflow.</p><div class="readiness-row"><span><i></i>Trust assurance</span><span class="pill amber">Pending</span></div><div class="readiness-row"><span><i></i>Live EPR connection</span><span class="pill amber">Pending</span></div><div class="readiness-row"><span><i></i>Clinical safety sign-off</span><span class="pill amber">Pending</span></div><button class="text-btn" onclick="nav('NHS')">Explore governance →</button></div><div class="panel"><h3>Transparent by design</h3><div class="progress"><span style="width:57.6%"></span><span style="width:19.6%"></span><span style="width:22.8%"></span></div><p class="fine">*Readiness is based on your supplied function inventory. This demo does not independently verify production functionality or NHS approval.</p><button class="text-btn" onclick="showAbout()">View source & scope ↗</button></div></aside></div>`}
function appointment(time,initials,name,detail,current){return `<div class="appointment ${current?'current':''}"><time>${time}</time><div class="avatar">${initials}</div><div class="details"><strong>${name}</strong><small>${detail}</small></div><button aria-label="View ${name}" onclick="patientDetail('${name}')">${icon('arrow')}</button></div>`}
function patientStrip(){return `<div class="patient-strip"><div class="avatar">MC</div><div class="meta"><h3>Maya Collins <span class="pill grey">Fictional patient</span></h3><p>Age 42 · Demo ID DEMO-001 · Community care follow-up</p></div><button class="text-btn" onclick="nav('patients')">Patient context ↗</button></div>`}
function cataloguePage(){return head('Every function. A clear status.','Explore all 158 capabilities, their dependencies and their place in the workspace.',`<button class="button-icon" onclick="exportCatalogue()">${icon('download')} Export catalogue</button>`)+`<div class="filters"><input id="catalogue-search" aria-label="Filter functions" placeholder="Search by name, ID or dependency…" value="${esc(search)}" oninput="search=this.value;renderResults()"><select aria-label="Category" onchange="filterCat=this.value;renderResults()"><option value="all">All categories</option>${categories.map(c=>`<option value="${c.key}" ${filterCat===c.key?'selected':''}>${c.name}</option>`).join('')}</select><select id="status-select" aria-label="Readiness status" onchange="filterStatus=this.value;renderResults()"><option value="all">All readiness statuses</option><option value="operational" ${filterStatus==='operational'?'selected':''}>Operational (91)</option><option value="pending" ${filterStatus==='pending'?'selected':''}>Not operational (36)</option>${Object.entries(statusInfo).map(([s,v])=>`<option value="${s}" ${filterStatus===s?'selected':''}>${v.label} (${count(s)})</option>`).join('')}</select></div><div id="results"></div><p class="inventory-note">Source: Clinical OS repository register, inspected 13 October 2026. Evidence: docs/clinical-workspace/FUNCTION_STATUS.md at commit 2be80acd. Exact function titles and limitations are now included. Repository test claims have not been rerun in this environment. All website actions are demo simulations.</p>`}
function getFiltered(){return features.filter(f=>(filterCat==='all'||f.cat===filterCat)&&(filterStatus==='all'||f.status===filterStatus||(filterStatus==='operational'&&['ready','enabled'].includes(f.status))||(filterStatus==='pending'&&['partial','external','approval','excluded'].includes(f.status)))&&(!search||(features.some(x=>x.id.toLowerCase()===search.trim().toLowerCase())?f.id.toLowerCase()===search.trim().toLowerCase():[f.id,f.title,f.detail,catFor(f.cat).name,statusInfo[f.status].label].join(' ').toLowerCase().includes(search.toLowerCase()))))}
function featureTable(list){return `<div class="table-wrap"><table><thead><tr><th>ID</th><th>Function</th><th>Readiness</th><th>Explore</th></tr></thead><tbody>${list.map(f=>`<tr><td>${f.id}</td><td><button onclick="feature('${f.id}')">${esc(f.title)}</button></td><td>${pill(f.status)}</td><td><button class="text-btn" aria-label="Details for ${f.id}" onclick="feature('${f.id}')">View ↗</button></td></tr>`).join('')}</tbody></table>${list.length?'':'<div class="empty">No matching functions. Try another search or readiness filter.</div>'}</div>`}
function renderResults(){const list=getFiltered();document.getElementById('results').innerHTML=`<div class="table-foot"><span><b>${list.length}</b> of 158 functions</span><button class="text-btn" onclick="catalogue()">Clear filters</button></div>`+featureTable(list)}
function categoryPage(key){const c=catFor(key);if(!c)return home();return head(c.name,c.desc,`<button class="button-icon" onclick="catalogue('all','${c.key}')">${icon('grid')} ${count(null,key)} functions</button>`)+`<div class="tab-bar"><button class="${categoryTab==='workflow'?'active':''}" onclick="categoryTab='workflow';render()">Interactive workspace</button><button class="${categoryTab==='functions'?'active':''}" onclick="categoryTab='functions';render()">All capabilities (${count(null,key)})</button></div>`+(categoryTab==='functions'?featureTable(features.filter(f=>f.cat===key)):({C:consultation,N:notes,F:forms,T:tasks,E:evidence,I:integrations,NHS:governance,DS:intelligence}[key]()))}
function consultation(){return patientStrip()+`<div class="work-grid"><div class="panel"><div class="panel-head"><h2>Consultation capture</h2><span class="pill grey">Simulation</span></div><label class="consent"><input type="checkbox" ${state.consent?'checked':''} ${recording?'disabled':''} onchange="state.consent=this.checked;audit('Demo consent '+(this.checked?'recorded':'withdrawn'));render()"><span>I have explained the recording process and recorded the fictional patient’s consent.<br><small>No microphone or real audio is used in this demo.</small></span></label><div class="recorder"><div class="record-time" id="record-time">${formatTime(seconds)}</div><div class="record-status" id="record-status">${recording?'Simulated capture in progress':state.captured?'Sample conversation captured':'Ready when you are'}</div><div class="wave ${recording?'recording':''}" id="wave">${Array.from({length:48},(_,i)=>`<i style="height:${8+Math.abs(Math.sin(i*2.3))*35}px;animation-delay:${i%8/10}s"></i>`).join('')}</div><div class="actions" style="justify-content:center"><button class="primary" ${!state.consent?'disabled':''} onclick="${recording?'pauseRecord()':'startRecord()'}">${recording?'Pause simulation':'Start simulation'}</button><button onclick="loadTranscript()" ${!state.consent?'disabled':''}>Load sample transcript</button><button onclick="resetRecording()">Reset</button></div></div><div class="actions"><button onclick="sampleUpload()">Use sample audio file</button><button onclick="feature('C05')">Interpretation</button><button onclick="feature('C20')">Offline capture</button></div><p class="fine">Speech engine: ${state.settings.speech?'enabled in demo settings':'off in demo settings'}. Capture controls are simulated. No audio is uploaded.</p></div><div class="panel"><div class="panel-head"><h2>Conversation</h2><span class="pill blue">Source preview</span></div>${state.captured?transcriptMarkup():`<div class="empty">${icon('mic')}<p>Record consent, then load the sample conversation.</p></div>`}<button class="primary wide" ${!state.captured?'disabled':''} onclick="draftNote()">Create sample consultation note →</button></div></div>`}
function formatTime(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function startRecord(){if(!state.consent)return;if(!state.settings.speech){toast('Enable the demo speech engine in Demo settings.');return}recording=true;render();recordTimer=setInterval(()=>{seconds++;const el=document.getElementById('record-time');if(el)el.textContent=formatTime(seconds);if(seconds>=8){pauseRecord();loadTranscript()}},1000)}
function pauseRecord(){clearInterval(recordTimer);recording=false;if(route==='C')render()}
function resetRecording(){pauseRecord();seconds=0;state.captured=false;audit('Simulated recording reset; sample transcript removed.');render()}
function loadTranscript(){if(!state.consent)return toast('Record fictional patient consent first.');if(!state.settings.speech)return toast('Enable the demo speech engine in Demo settings.');pauseRecord();state.captured=true;seconds=148;audit('Sample transcript loaded. No real audio recorded.');render()}
function sampleUpload(){if(!state.consent)return toast('Record fictional patient consent first.');loadTranscript()}
function transcriptMarkup(){return `<div class="transcript"><time>00:12 · Clinician</time><strong>Dr Jamie Morgan</strong>What would you like us to focus on today?</div><div class="transcript"><time>00:24 · Patient</time><strong>Maya Collins</strong>I’d like to talk about my sleep and how it affects my working day. I’ve been keeping a diary.</div><div class="transcript"><time>01:42 · Clinician</time><strong>Dr Jamie Morgan</strong>We can review your diary together and arrange a follow-up. Which day usually works for you?</div><div class="transcript"><time>02:08 · Patient</time><strong>Maya Collins</strong>A Tuesday morning would work best.</div><button class="source" onclick="sourceDetail('Sample consultation transcript','Fictional scripted conversation, 00:12–02:08. No audio file or transcription provider is connected.')">View transcript source ↗</button>`}
const sampleNote='SUBJECTIVE\nMaya would like to discuss sleep and its effect on her working day. She reports keeping a diary.\n\nOBJECTIVE\nNo objective observations or examination findings documented in this sample transcript.\n\nASSESSMENT\nNo diagnosis or clinical assessment inferred. Clinician review required.\n\nPLAN\nReview the patient’s diary together. Arrange a follow-up; Tuesday morning is the stated preference.';
function draftNote(){if(!state.settings.ai)return toast('Enable AI drafting in Demo settings to use the scripted preview.');if(state.signed){nav('N');toast('The signed sample is protected. Create an amendment before changing it.');return}state.note=sampleNote;audit('Scripted note prepared from the sample transcript; clinician review required.');nav('N')}
function notes(){return patientStrip()+`<div class="work-grid"><section class="panel"><div class="panel-head"><h2>Consultation note</h2>${state.signed?'<span class="pill green">Signed · Demo only</span>':'<span class="pill amber">Draft · Review required</span>'}</div><div class="form-group"><label for="note-template">Document template</label><select class="field" id="note-template" ${state.signed?'disabled':''} onchange="changeTemplate(this.value)"><option value="soap">SOAP consultation note</option><option value="referral">Referral letter</option><option value="summary">Patient-friendly summary</option><option value="mdt">MDT handover</option></select></div><label for="note-text" class="fine">Editable fictional note · Do not enter real patient information</label><textarea id="note-text" class="field note-editor" ${state.signed?'readonly':''} placeholder="Load the sample note or capture a sample conversation first." oninput="state.note=this.value;save()">${esc(state.note)}</textarea><div class="actions" style="margin-top:16px"><button ${state.signed?'disabled':''} onclick="draftNote()">Load sample note</button><button ${state.signed?'disabled':''} onclick="saveNote()">Save draft</button>${state.signed?'<button onclick="amendNote()">Create amendment</button>':'<button class="primary" onclick="reviewNote()">Review & sign</button>'}<button onclick="exportNote()">Export</button></div><p class="fine">Version ${state.version} · Drafting is scripted. A demo signature is not a legal or clinical signature.</p></section><aside><div class="panel"><div class="panel-head"><h3>Source & quality check</h3>${icon('shield')}</div><div class="readiness-row"><span>Patient preference preserved</span><span class="pill green">Sample</span></div><div class="readiness-row"><span>Objective findings</span><span class="pill amber">Not documented</span></div><div class="readiness-row"><span>Clinician review</span><span class="pill ${state.signed?'green':'amber'}">${state.signed?'Recorded':'Required'}</span></div><button class="text-btn" onclick="modal('Transcript source',transcriptMarkup())">Compare with transcript ↗</button><p class="fine">Indicators describe the scripted sample. They do not analyse edits or verify clinical accuracy.</p></div><div class="panel"><h3>Next in the workflow</h3><p class="fine">After review, create a follow-up task or preview the EPR handoff.</p><button class="wide" onclick="createFollowup()">Create follow-up task</button><button class="wide" onclick="nav('I')">Preview EPR handoff →</button><button class="text-btn" style="margin-top:15px" onclick="showHistory()">Version history ↗</button></div></aside></div>`}
function changeTemplate(type){if(state.signed)return;state.note=type==='soap'?sampleNote:type==='referral'?'DRAFT REFERRAL — FICTIONAL EXAMPLE\n\nPatient: Maya Collins (DEMO-001)\nReason for referral: [Clinician to specify]\nRelevant history: Patient wishes to discuss sleep and its effect on her working day.\nRequested action: [Clinician to review and complete]':type==='summary'?'YOUR APPOINTMENT SUMMARY — FICTIONAL EXAMPLE\n\nWe discussed your wish to review sleep and its effect on your working day.\nNext steps: Review your diary together and arrange a follow-up.\nYour preference: Tuesday morning.\n\nPlease ask your care team if anything in this summary is unclear.':'MDT HANDOVER — FICTIONAL EXAMPLE\n\nPatient: Maya Collins (DEMO-001)\nPatient priority: Discuss sleep and its effect on her working day.\nAgreed administrative action: Arrange follow-up, preferably Tuesday morning.\nClinical assessment: Not inferred. Clinician input required.';save();document.getElementById('note-text').value=state.note}
function saveNote(){if(state.signed||!state.note.trim())return toast('Add a draft note first.');state.history.unshift({version:state.version,text:state.note,status:'Draft saved'});const saved=audit('Draft note version '+state.version+' saved locally.');toast(saved?'Draft saved in this browser.':'Draft remains in this tab only. Saving failed.')}
function reviewNote(){if(!state.note.trim())return toast('Add a draft note first.');modal('Review before signing',`<p>Confirm that you have reviewed the fictional note against its source. This records a demo review only.</p><label class="consent"><input type="checkbox" id="review-confirm"><span>I have checked the note, including missing information and patient preferences.</span></label>`,`<button onclick="closeModal()">Back to draft</button><button class="primary" onclick="signNote()">Sign demo note</button>`)}
function signNote(){if(!document.getElementById('review-confirm').checked)return toast('Confirm the review before signing.');state.signed=true;state.history.unshift({version:state.version,text:state.note,status:'Signed in demo'});audit('Demo note version '+state.version+' reviewed and signed by fictional Dr Morgan.');closeModal();render();toast('Demo note signed. Create an amendment for further changes.')}
function amendNote(){state.signed=false;state.version++;audit('Amendment opened as note version '+state.version+'.');render()}
function showHistory(){modal('Document version history',state.history.length?state.history.map(h=>`<details><summary>Version ${h.version} · ${esc(h.status)}</summary><pre style="white-space:pre-wrap;font-size:11px">${esc(h.text)}</pre></details>`).join(''):'<p>No versions saved yet. Save a draft or sign the sample note.</p>')}
function exportNote(){if(!state.note.trim())return toast('Add a note before exporting.');audit('Demo note exported as text.');download('fictional-consultation-note.txt',`DEEPSYNAPS CLINICAL ADMIN — FICTIONAL DEMO ONLY\nVersion ${state.version} | ${state.signed?'Demo reviewed and signed':'UNSIGNED DRAFT'}\n\n${state.note}\n\nLOCAL DEMO AUDIT\n${state.audit.map(a=>a.time+' '+a.text).join('\n')}`,'text/plain')}
function forms(){return patientStrip()+`<div class="work-grid"><div class="panel"><div class="panel-head"><h2>Follow-up preference form</h2><span class="pill grey">Template v1</span></div><p class="fine">Demonstrates source-linked field filling and clinician review. No real files or questionnaires are submitted.</p><button class="button-icon" onclick="state.formFilled=true;state.formReviewed=false;audit('Sample follow-up form filled from scripted sources.');render()">${icon('spark')} Fill from sample sources</button>${[['Patient name','Maya Collins','Fictional patient record'],['Preferred day','Tuesday morning','Sample transcript · 02:08'],['Purpose of follow-up','Review diary together','Sample transcript · 01:42']].map(([label,val,source])=>`<div class="form-group"><label>${label}<input class="field" readonly value="${state.formFilled?val:''}" placeholder="Awaiting source"></label>${state.formFilled?`<button class="source" onclick="sourceDetail('${source}','${val}')">${source} ↗</button>`:''}</div>`).join('')}<label class="consent"><input type="checkbox" ${state.formReviewed?'checked':''} ${!state.formFilled?'disabled':''} onchange="state.formReviewed=this.checked;save();render()"><span>I have reviewed all fields against their sources.</span></label><button class="primary wide" ${!state.formReviewed?'disabled':''} onclick="audit('Sample form queued locally after review; nothing sent.');toast('Form queued in this demo. Nothing sent to a patient or EPR.')">Approve demo form</button></div><div><div class="panel"><h3>Template & assessment library</h3><div class="chips">${['F01','F03','F04','F10','F11'].map(id=>`<button onclick="feature('${id}')">${({F01:'Form templates',F03:'Organisation forms',F04:'Assessments',F10:'Mental health',F11:'Barthel · Lawton · MUST'})[id]}</button>`).join('')}</div><p class="fine">Instrument content and scoring are not reproduced or clinically validated in this demo.</p><button class="wide" onclick="feature('F05')">PDF field detection</button><button class="wide" onclick="feature('F09')">OCR & scanned documents</button><button class="wide" onclick="feature('F12')">Patient form delivery</button></div><div class="notice">Every filled field has a visible source. Approval is required before a submission could occur in a connected deployment.</div></div></div>`}
function tasks(){return `<div class="work-grid"><div class="panel"><div class="panel-head"><h2>Team task board</h2><span class="pill green">${state.tasks.filter(t=>!t.done).length} open</span></div>${state.tasks.map((t,i)=>`<div class="task ${t.done?'done':''}"><input type="checkbox" aria-label="Complete ${esc(t.text)}" ${t.done?'checked':''} onchange="state.tasks[${i}].done=this.checked;audit('Demo task '+(this.checked?'completed':'reopened')+': '+state.tasks[${i}].text);render()"><div class="task-text"><strong>${esc(t.text)}</strong><small>Fictional workflow · Today</small></div><select aria-label="Assign task ${i+1}" onchange="state.tasks[${i}].owner=this.value;audit('Demo task reassigned to '+this.value)">${['Dr Morgan','Care team','Admin team'].map(o=>`<option ${t.owner===o?'selected':''}>${o}</option>`).join('')}</select></div>`).join('')}<form onsubmit="event.preventDefault();addTask(this.task.value);this.reset()" style="margin-top:20px"><label class="fine" for="new-task">Add a fictional administrative task</label><div class="filters"><input id="new-task" name="task" required maxlength="150" placeholder="e.g. Confirm preferred appointment time"><button class="primary">Add task</button></div></form></div><aside><div class="panel"><h3>Today’s workload</h3><div class="mini-stats"><div><strong>${state.tasks.length}</strong><small>Total demo tasks</small></div><div><strong>${state.tasks.filter(t=>t.done).length}</strong><small>Completed</small></div></div><button class="wide" onclick="createFollowup()">Add sample follow-up</button><button class="wide" onclick="feature('T04')">Preview SMS follow-up</button><button class="wide" onclick="feature('T07')">Safeguarding escalation</button></div><div class="notice amber">Telephony functions require a contract. This demo places no calls, sends no SMS and performs no unsupervised triage.</div></aside></div>`}
function addTask(text){text=text.trim();if(!text)return;state.tasks.push({text,owner:'Care team',done:false});audit('Fictional administrative task added.');render();toast('Task added to the demo board.')}
function createFollowup(){if(!state.signed)return toast('Review and sign the demo note before creating its follow-up.');const text='Arrange Maya’s follow-up — Tuesday morning preferred';if(state.tasks.some(t=>t.text===text))return nav('T');state.tasks.push({text,owner:'Care team',done:false});audit('Follow-up task created from signed demo note.');nav('T');toast('Follow-up task added; no appointment or message sent.')}
function evidence(){return patientStrip()+`<div class="work-grid"><div class="panel"><h2>Pre-appointment briefing</h2><div class="notice">Sample chart preparation from fictional DeepSynaps records. No external clinical record or guideline search is connected.</div><div class="timeline-item"><small>Patient-stated priority</small><h3>Sleep and the working day</h3><p>Wants to review a diary together at the appointment.</p><button class="source" onclick="sourceDetail('Sample transcript · 00:24','Patient-stated goal; no diagnosis inferred.')">View source ↗</button></div><div class="timeline-item"><small>Patient preference</small><h3>Tuesday morning follow-up</h3><p>Include this preference when coordinating care.</p><button class="source" onclick="sourceDetail('Sample transcript · 02:08','A Tuesday morning would work best.')">View source ↗</button></div><div class="timeline-item"><small>Important missing information</small><h3>Allergies and medication not supplied</h3><p>Verify with the patient and authorised record. Missing information is not treated as “none”.</p></div><button onclick="nav('C')">Open consultation →</button></div><div><div class="panel"><h3>Evidence tools</h3><p class="fine">Explore capabilities and their stated readiness.</p>${['E01','E03','E04','E07','E09','E10','E11'].map(id=>`<button class="wide" onclick="feature('${id}')">${features.find(f=>f.id===id).title} ↗</button>`).join('')}</div></div></div>`}
function integrations(){return `<div class="work-grid"><div class="panel"><div class="panel-head"><h2>EPR handoff preview</h2><span class="pill amber">Not connected</span></div>${patientStrip()}<div class="audit-row"><span class="step-number">1</span><div><strong>Document prepared</strong><br>${state.note?'Sample note available':'Create a sample note first'}</div></div><div class="audit-row"><span class="step-number">2</span><div><strong>Clinician review & signature</strong><br>${state.signed?'Demo review recorded':'Review required'}</div></div><div class="audit-row"><span class="step-number">3</span><div><strong>Authorised EPR submission</strong><br>Awaiting RiO / EMIS authorisation</div></div><div class="audit-row"><span class="step-number">4</span><div><strong>Receipt and retention policy</strong><br>No EPR acknowledgement received. No recording deletion triggered.</div></div><div class="actions" style="margin-top:20px"><button onclick="nav('N')">Open note</button><button class="primary" ${!state.signed?'disabled':''} onclick="previewHandoff()">Preview handoff payload</button></div><div class="notice amber">This is a local workflow preview. It cannot write to RiO, EMIS or NHS systems. The payload is illustrative JSON, not a validated FHIR export.</div></div><aside><div class="panel"><h3>Integration readiness</h3>${[['Identifier mapping','I01'],['Internal sandbox','I09'],['FHIR export','NHS01'],['NHS Number matching','NHS03'],['NHS login / CIS2','NHS02'],['Partner API','DS29']].map(([label,id])=>`<div class="readiness-row"><button class="text-btn" onclick="feature('${id}')">${label} ↗</button>${pill(features.find(f=>f.id===id).status)}</div>`).join('')}</div><div class="panel"><h3>System boundaries</h3><p class="fine">Clinician approval → authorised integration → confirmed receipt → approved retention action.</p><button class="text-btn" onclick="feature('I04')">Recording deletion dependency ↗</button></div></aside></div>`}
function previewHandoff(){if(!state.signed)return;modal('Illustrative handoff payload',`<p>No request is sent. This JSON illustrates information moving through the workflow.</p><pre style="white-space:pre-wrap;font-size:11px;background:#f3f7f6;padding:15px;border-radius:6px">${esc(JSON.stringify({demo:true,patientReference:'DEMO-001',documentVersion:state.version,review:'demo-signed',destination:'Not connected',submissionStatus:'NOT_SUBMITTED',document:state.note},null,2))}</pre>`);audit('Illustrative EPR payload previewed; no submission made.')}
function governance(){return `<div class="work-grid"><div><div class="panel"><div class="panel-head"><h2>NHS readiness & assurance</h2><span class="pill amber">Deployment gates open</span></div><p class="fine">Track the evidence and approvals needed for a Trust deployment. This demo is not evidence of NHS compliance or accreditation.</p>${features.filter(f=>f.status==='approval').map(f=>`<div class="toggle-row"><div><strong>${f.id} · ${f.title}</strong><p>Named owner and sign-off not supplied</p></div><button class="text-btn" onclick="feature('${f.id}')">Review ↗</button></div>`).join('')}</div></div><aside><div class="panel"><h3>Local demo activity log</h3><p class="fine">Visible interaction history only. This browser log is editable local storage, not a tamper-evident production audit.</p>${state.audit.slice(0,8).map(a=>`<div class="audit-row"><time>${a.time}</time><span>${esc(a.text)}</span></div>`).join('')}<button class="wide" onclick="download('demo-activity-log.json',JSON.stringify(state.audit,null,2),'application/json')">Export demo log</button></div><div class="panel"><h3>Explicitly excluded</h3><p class="fine">Autonomous prescribing, unsupervised triage and self-training on identifiable NHS data remain outside scope.</p><button class="text-btn" onclick="catalogue('excluded')">See all 5 exclusions ↗</button></div></aside></div>`}
function intelligence(){return `<div class="notice">These are reported existing DeepSynaps modules. Cards explain their role; no live analysis, agent or patient connection runs in this demo.</div><div class="modules">${features.filter(f=>f.cat==='DS').map(f=>`<button class="module" onclick="feature('${f.id}')">${pill(f.status)}<h3>${f.title}</h3><p>${f.id} · Explore role & readiness ↗</p></button>`).join('')}</div><div class="journey">${icon('spark')}<div><h3>Part of the Clinical Intelligence OS</h3><p>Clinical Admin brings everyday workflows together with the wider DeepSynaps platform.</p></div><a href="https://app.deepsynaps.com/" target="_blank" rel="noopener noreferrer">Open main platform ↗</a></div>`}
function patientPage(){return head('Patients & appointments','A fictional clinic day, with patient context ready before the conversation.',`<button class="primary" onclick="nav('C')">Open Maya’s consultation</button>`)+`<div class="work-grid"><div class="panel"><h2>Tuesday’s appointments</h2>${appointment('09:15','MC','Maya Collins','Follow-up · Community care',true)}${appointment('10:00','AT','Alex Taylor','Initial consultation',false)}${appointment('10:45','SW','Sam Wilson','Care plan review',false)}<p class="fine">All names, appointment details and records shown here are fictional.</p></div><div class="panel"><h2>Maya’s patient context</h2><p class="fine">DEMO-001 · Age 42 · No real NHS Number</p><div class="timeline-item"><small>Today · Patient priority</small><p>Discuss sleep and the impact on the working day.</p></div><div class="timeline-item"><small>Today · Source document</small><p>Patient reports keeping a diary; its contents are not included.</p></div><div class="timeline-item"><small>Follow-up preference</small><p>Tuesday morning.</p></div><button class="wide" onclick="nav('E')">Open pre-appointment briefing →</button></div></div>`}
function patientDetail(name){if(name==='Maya Collins')return nav('patients');modal(name+' — fictional record',`<p>${name==='Alex Taylor'?'Initial consultation · 10:00':'Care plan review · 10:45'}</p><p>This fictional schedule entry shows how an appointment is presented. Maya Collins is the fully scripted patient journey in this demo.</p>`,`<button onclick="closeModal()">Close</button><button class="primary" onclick="closeModal();nav('C')">Explore Maya’s consultation</button>`)}
function settingsPage(){return head('Demo settings','Explore service dependencies without connecting external services.')+`<div class="work-grid"><div class="panel"><h2>Simulated service switches</h2>${[['ai','AI drafting','Allows the predefined note drafting preview. No AI provider is called.'],['speech','Speech engine','Allows the sample transcript. No microphone or speech service is used.'],['sms','SMS service','Changes the SMS preview state. No message is sent.']].map(([key,title,desc])=>`<div class="toggle-row"><div><strong>${title}</strong><p>${desc}</p></div><button role="switch" aria-checked="${state.settings[key]}" aria-label="${title}" class="switch" onclick="state.settings.${key}=!state.settings.${key};audit('${title} simulation '+(state.settings.${key}?'enabled':'disabled'));render()"></button></div>`).join('')}<div class="notice">These switches only affect this demo. They do not configure the production product or change any capability’s reported readiness.</div></div><aside class="panel"><h3>Reset your walkthrough</h3><p class="fine">Demo notes, tasks, settings and activity are saved in this browser only. Use fictional content throughout.</p><button onclick="confirmReset()">Reset demo data</button><button class="wide" onclick="showAbout()">Source & demo scope</button></aside></div>`}
function resetDemo(){state=initial();seconds=0;const loadFailed=storageLoadFailed;storageLoadFailed=false;const saved=save();if(!saved){storageLoadFailed=loadFailed;showStorageStatus();}closeModal();nav('home');toast(saved?'Demo reset.':'Reset applies to this tab only. Saving failed; previous saved records may return after reload.')}
function confirmReset(){modal('Reset this demo?',`<p>This replaces the saved demo notes, tasks and settings with the fictional starting records. If the saved data could not be loaded, export its original value before resetting. This cannot be undone.</p>`,`<button onclick="closeModal()">Cancel</button><button class="primary" onclick="resetDemo()">Reset demo</button>`)}
function feature(id){const f=features.find(x=>x.id===id);if(!f)return;const special={T04:state.settings.sms?'SMS demo service is enabled. Example: “Your care team will contact you to confirm your preferred follow-up time.” No message is sent.':'Enable the SMS demo switch to preview a follow-up message. No message is sent.',T07:'Safeguarding concerns must be escalated to a human care team. This demo does not detect, assess or triage risk.',DS26:'The reported implementation remembers writing preferences only, not agent task outcomes.'};modal(f.title,`<div style="display:flex;gap:10px;margin-bottom:18px"><span class="pill grey">${f.id}</span>${pill(f.status)}</div><p>${esc(statusInfo[f.status].description)}</p>${f.detail?`<div class="notice ${['partial','external','approval'].includes(f.status)?'amber':''}">${esc(f.detail)}</div>`:''}${special[id]?`<p>${esc(special[id])}</p>`:''}<dl><dt>Category</dt><dd>${catFor(f.cat).name}</dd><dt>Source</dt><dd>Clinical OS repository register, commit 2be80acd</dd><dt>Evidence</dt><dd><code>docs/clinical-workspace/FUNCTION_STATUS.md</code><br>Register and API source inspected; upstream tests not rerun here.</dd><dt>Here you can</dt><dd>${f.status==='excluded'?'Inspect the scope boundary. This action is intentionally unavailable.':f.status==='linked'?'Explore the module’s place in the wider platform. Live module requires the main DeepSynaps application.':'Explore a representative category workflow. This is not an individual end-to-end implementation of every listed function.'}</dd></dl>`,`<button onclick="closeModal()">Close</button>${f.status==='excluded'?'':`<button class="primary" onclick="closeModal();nav('${f.cat}')">Open ${catFor(f.cat).short} →</button>`}`)}
function sourceDetail(title,detail){modal('Source: '+title,`<p>${esc(detail)}</p><span class="pill grey">Fictional demonstration source</span>`)}
function modal(title,body,foot='<button onclick="closeModal()">Close</button>'){const d=document.getElementById('dialog');d.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${esc(title)}</h2><button class="close" aria-label="Close dialog" onclick="closeModal()">×</button></div><div class="modal-body">${body}</div><div class="modal-foot">${foot}</div>`;if(!d.open)d.showModal()}
function closeModal(){document.getElementById('dialog').close()}
function showAbout(){modal('About this workspace',`<p><strong>A product demonstration for NHS conversations.</strong> Explore 158 functions and representative workflows using fictional records.</p><p>Readiness labels reproduce the supplied inventory: 68 out of the box, 23 requiring services, 31 linked modules, 9 partial, 14 external dependencies, 8 sign-offs and 5 excluded.</p><p>The source points to <code>docs/clinical-workspace/FUNCTION_STATUS.md</code>. That repository file and its tests were not available for independent inspection in this build.</p><p>Fourteen dependency-only entries have no individual title in the supplied list. They remain listed by ID with this limitation shown. The Tasks service-dependent subheading said six, but listed five; those five give the stated total of 23.</p><p>Notes, tasks and settings are stored locally in your browser. No live AI, recording, SMS, EPR, patient upload or clinical analysis is connected. The demo is not an NHS endorsement, compliance certification or clinical tool.</p><p>FHIR profile applicability is left unverified rather than repeating an unverified assertion about UK Core profiles.</p>`)}
const tour=[{route:'home',title:'One workspace, 158 functions',text:'Start with the eight categories. Each capability has a transparent readiness label. Use All functions to search by ID, name or dependency.'},{route:'patients',title:'Prepare before the appointment',text:'Meet Maya Collins, our fictional patient. The briefing preserves her stated goals and marks missing information explicitly.'},{route:'C',title:'Consent comes first',text:'Close this guide to record fictional consent, then load the sample transcript. Capture controls never access your microphone.'},{route:'N',title:'Review the documentation',text:'Load the sample note, edit it and use Review & sign. A signed demo note is read-only until an amendment is created.'},{route:'F',title:'Keep the source beside the field',text:'Fill the sample form, inspect each field’s source and record a review before approval.'},{route:'T',title:'Coordinate the follow-up',text:'Assign tasks, complete actions and add a fictional administrative task. No communications are sent.'},{route:'I',title:'See the integration boundary',text:'The handoff preview shows review and submission stages. Live RiO / EMIS authorisation and an EPR acknowledgement remain outstanding.'},{route:'catalogue',title:'Explore everything',text:'All 158 function IDs are searchable. Filter by category and readiness, inspect dependencies, or export the inventory.'}];
function startTour(){tourIndex=0;showTour()}
function showTour(){const step=tour[tourIndex];nav(step.route);modal(step.title,`<div class="eyebrow">WALKTHROUGH ${tourIndex+1} / ${tour.length}</div><p>${step.text}</p>`,`<button onclick="closeModal()">Explore this screen</button>${tourIndex?'<button onclick="tourIndex--;showTour()">Back</button>':''}<button class="primary" onclick="${tourIndex<tour.length-1?'tourIndex++;showTour()':'closeModal()'}">${tourIndex<tour.length-1?'Next →':'Finish'}</button>`)}
function download(filename,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo export prepared.')}
function exportCatalogue(){const quote=v=>'"'+String(v).replace(/"/g,'""')+'"';const rows=[['ID','Category','Function','Reported readiness','Dependency / limitation'],...getFiltered().map(f=>[f.id,catFor(f.cat).name,f.title,statusInfo[f.status].label,f.detail])];download('clinical-admin-function-catalogue.csv','\uFEFF'+rows.map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
document.getElementById('dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
const initialRoute=location.hash.slice(1);if(['home','catalogue','patients','settings',...categories.map(c=>c.key)].includes(initialRoute))route=initialRoute;render();

// Hash links and browser history must resolve through the same navigation path.
window.addEventListener?.('hashchange',()=>{
 const target=location.hash.slice(1)||'home';
 if(['home','catalogue','patients','settings','organisation','extensions','connections','delivery','loops',...categories.map(c=>c.key)].includes(target)&&target!==route)nav(target);
});

showStorageStatus();
